design_text:
{
  "site_summary": "Your courtyard is a full shade, low moisture walled space with rain-shadowed dry walls and no pets.",
  "layout_strategy": "The scheme is structured with upright structural perennials forming the mid height against the dry walls, and a robust low layer filling the ground level containers to create depth.",
  "combination_logic": "The plants combine glossy strap-like foliage with architectural structure and upright leafy forms, offering seasonal blooms and reliable year-round green texture in a dark environment.",
  "zones": [
    {
      "zone_name": "Mid-Height Wall Accents",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "against the north-facing courtyard wall at knee to waist height, receiving full shade and low moisture.",
      "plants": [
        {
          "scientific_name": "Clivia miniata",
          "common_name": "Kaffir Lily",
          "why": "Thrives in full shade and brings vibrant seasonal flowers to a dark corner.",
          "role_in_combination": "Provides glossy, dark green strap-like foliage and striking orange trumpet flowers that light up the shade."
        },
        {
          "scientific_name": "Clivia spp.",
          "common_name": "Clivia Lily",
          "why": "Complements the main focal plant with matching shade tolerance and similar architectural form.",
          "role_in_combination": "Reinforces the structural leaf rhythm and adds depth to the mid layer with its bold foliage."
        }
      ],
      "maintenance": [
        "Water moderately when the top few inches of soil are dry.",
        "Apply a balanced liquid fertiliser every month during spring and summer.",
        "Remove spent flower stems at the base after blooming finishes.",
        "Repot every two to three years only when roots become tightly crowded."
      ]
    },
    {
      "zone_name": "Ground Level Foliage Layer",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "at the base of the courtyard walls on the floor, fully shaded with low moisture conditions.",
      "plants": [
        {
          "scientific_name": "Beaucarnea recurvata",
          "common_name": "Pony Tail Palm",
          "why": "Brings a unique sculptural element to the ground level and tolerates low moisture well.",
          "role_in_combination": "Acts as an architectural anchor with its swollen base and arching, ribbon-like leaves, contrasting with the strap leaves above."
        }
      ],
      "maintenance": [
        "Water sparingly as the swollen trunk stores water effectively.",
        "Feed with a weak liquid fertiliser once in mid-spring.",
        "Wipe dust from the long leaves occasionally to keep them healthy.",
        "Repot only when the base completely fills the container."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels in the containers to prevent under or overwatering",
      "frequency": "every two weeks",
      "season": "summer"
    },
    {
      "task": "Apply a balanced liquid fertiliser to support active growth",
      "frequency": "monthly",
      "season": "spring"
    },
    {
      "task": "Inspect plants for dead foliage and clear away debris from the soil surface",
      "frequency": "once a month",
      "season": "autumn"
    }
  ],
  "care_cautions": [
    "Overwatering the Clivia plants in the rain-shadowed dry shade can lead to root rot.",
    "Underwatering the Pony Tail Palm during prolonged dry spells may cause leaf tip dieback."
  ],
  "pet_safety_note": "No pets live in the household, so the design focuses entirely on aesthetic appeal and architectural structure."
}
